      previo: 'pedidos = [\n    {"pedido_id": 1, "cliente_id": 10, "monto": 99.9, "canal": "web"},\n    {"pedido_id": 2, "cliente_id": None, "monto": 50, "canal": "app"},\n    {"pedido_id": 3, "cliente_id": 11, "monto": -5, "canal": "fax"},\n    {"pedido_id": 4, "monto": "120", "canal": "tienda"},\n    {"pedido_id": 5, "cliente_id": 12, "monto": 0, "canal": "web"},\n]',
