      solucion: 'from datetime import datetime, timedelta\npor_usuario = {}\nfor u, t in clics:\n    por_usuario.setdefault(u, []).append(datetime.strptime(t, "%Y-%m-%d %H:%M"))\nresultado = {}\nfor u, ts in por_usuario.items():\n    ts.sort()\n    sesiones = 1\n    for a, b in zip(ts, ts[1:]):\n        if b - a > timedelta(minutes=30):\n            sesiones += 1\n    resultado[u] = sesiones',
