      criterios: ['Reintenta solo ante <code>ErrorTemporal</code>', 'Esperas de 1, 2, 4… segundos con <code>base = 1</code>', 'Si se agotan los intentos, el error se relanza', '<code>resultado</code> = valor devuelto por <code>con_reintentos(api, 5, 1)</code>'],
      previo: 'class ErrorTemporal(Exception):\n    pass\n\nesperas = []\ndef esperar(s):\n    esperas.append(s)\n\nllamadas = {"n": 0}\ndef api():\n    llamadas["n"] += 1\n    if llamadas["n"] < 4:\n        raise ErrorTemporal("503")\n    return {"ok": True, "intentos": llamadas["n"]}',
      test: 'assert "con_reintentos" in dir() or "con_reintentos" in globals(), "Falta la función con_reintentos"\nassert resultado == {"ok": True, "intentos": 4}, "resultado debe ser lo que devuelve la API al cuarto intento"\nassert esperas == [1, 2, 4], "Las esperas deben ser 1, 2 y 4 segundos; fueron %s" % esperas\nllamadas["n"] = -100\nesperas.clear()\ntry:\n    con_reintentos(api, 3, 1)\n    raise AssertionError("Con 3 intentos y una API que sigue fallando, la función debe relanzar ErrorTemporal")\nexcept ErrorTemporal:\n    pass',
      practica: ['python-errores', 'incidentes-apis-credenciales-y-costos'],
      pistas: ['Un bucle <code>for n in range(1, intentos + 1)</code> con <code>try/except ErrorTemporal</code>.', 'Si es el último intento, haz <code>raise</code> para relanzar el error.', 'Antes de reintentar: <code>esperar(base * 2 ** (n - 1))</code>.'],
      solucion: 'def con_reintentos(funcion, intentos, base):\n    for n in range(1, intentos + 1):\n        try:\n            return funcion()\n        except ErrorTemporal:\n            if n == intentos:\n                raise\n            esperar(base * 2 ** (n - 1))\n\nresultado = con_reintentos(api, 5, 1)',
