      criterios: ["Usa <code>{{ ref('stg_pagos') }}</code> y <code>{{ ref('stg_pedidos') }}</code>", 'Devuelve <code>pago_id</code>, <code>pedido_id</code>, <code>motivo</code> (<code>monto</code> o <code>fecha</code>)', 'Solo pagos aprobados que violan alguna de las dos reglas'],
