      practica: ['aws-s3-data-lake'], pistas: ['Configura credenciales con <code>aws configure</code>.', '<code>aws s3 mb s3://nombre-unico</code>.', '<code>aws s3 cp carpeta s3://bucket/crudo/ --recursive</code>.'],
